}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller) public {
        // Ensure caller is not the owner
        vm.assume(caller != address(this));

        // Record contract balance before call
        uint256 balanceBefore = address(c).balance;

        // Call withdrawAll as a non-owner
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", address(0x1234)));

        // Assert that the call reverted (since require(false) in mutated version ensures it always reverts, but in reference it should not revert for non-owner)
        // Actually, we want a general rule that distinguishes them:
        // Reference: non-owner call reverts due to require(msg.sender == owner), so contract balance unchanged.
        // Mutant: non-owner call reverts due to require(false), so contract balance unchanged.
        // Both revert, so we cannot distinguish by revert. Instead, we need a call that succeeds in reference but not in mutant.
        // Let's try owner call.
    }

    function testFuzz_property_owner(address recipient) public {
        // Owner is address(this)
        uint256 balanceBefore = address(c).balance;

        // Call withdrawAll as owner
        c.withdrawAll(recipient);

        // Assert that after call, contract balance is zero
        assertTrue(address(c).balance == 0, "Contract balance should be zero after owner withdrawAll");
    }
}

