pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != address(c));
        uint256 balanceBefore = address(c).balance;
        vm.deal(address(c), 1 ether);
        vm.prank(caller);
        bool reverted;
        try c.withdrawAll(address(0x1234)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfter = address(c).balance;
        assertTrue(reverted == (caller != address(this)));
        assertTrue((balanceAfter == 0) == (caller == address(this)));
    }
}

